import ReactDOM from 'react-dom/client';

const path = window.location.pathname;
const isFraudPage = path.includes('fraud');
const isDarkStorePage = path.includes('dark_store');

const App = isDarkStorePage
 ? lazy(() => import('./dark-store-app'))
 : isFraudPage
 ? lazy(() => import('./fraud-app'))
 : lazy(() => import('./app'));

ReactDOM.createRoot(document.getElementById('root')!).render(
 <Suspense fallback={null}>
 <App />
 </Suspense>
);
